package entity

import (
	"encoding/json"
	"strings"
	"time"

	"github.com/loopopen/gap/internal/enum"
)

type MessageFilter struct {
	ID          *uint
	Status      enum.Status
	Topic       string
	Group       string
	CreatedFrom *time.Time
	CreatedTo   *time.Time
	HeaderKey   string
	HeaderValue string
	Payload     string
	Descending  bool
}

// HeaderLikePattern returns a portable SQL LIKE pattern for the compact JSON
// generated by Envelope.HeadersBytes. Key-only and value-only filters are
// supported in addition to an exact key/value pair.
func (f *MessageFilter) HeaderLikePattern() string {
	if f == nil || f.HeaderKey == "" && f.HeaderValue == "" {
		return ""
	}

	var fragment string
	if f.HeaderKey != "" {
		key, _ := json.Marshal(f.HeaderKey)
		fragment = string(key) + ":"
	}
	if f.HeaderValue != "" {
		value, _ := json.Marshal(f.HeaderValue)
		if f.HeaderKey == "" {
			fragment = ":"
		}
		fragment += string(value)
	}

	replacer := strings.NewReplacer("!", "!!", "%", "!%", "_", "!_")
	return "%" + replacer.Replace(fragment) + "%"
}
